import gurobipy
from gurobipy import GRB
m = gurobipy.Model()
m.Params.MIPGap = 1e-06
item_params = {}
category_params = {}
resource_capacity = {}
usage = {}
bundle_params = {}
requires = []
incompatible = []
for record in CSVQA_DATA['logical_records'].get('item', []):
    v = record['values']
    ref = v['item_ref']
    authorized = int(v['authorized'])
    cat = v['category']
    min_lot = int(v['minimum_lot'])
    max_order = int(v['maximum_order'])
    unit_benefit = int(v['unit_benefit_cents'])
    item_fee = int(v['item_fee_cents'])
    if authorized == 0:
        min_lot = 0
        max_order = 0
    item_params[ref] = {'category': cat, 'min_lot': min_lot, 'max_order': max_order, 'unit_benefit': unit_benefit, 'item_fee': item_fee}
for record in CSVQA_DATA['logical_records'].get('category', []):
    v = record['values']
    cat = v['category']
    min_q = int(v['minimum_quantity'])
    max_q = int(v['maximum_quantity'])
    activation_fee = int(v['activation_fee_cents'])
    category_params[cat] = {'min_q': min_q, 'max_q': max_q, 'activation_fee': activation_fee}
for record in CSVQA_DATA['logical_records'].get('capacity_ledger', []):
    v = record['values']
    res = v['resource']
    amt = int(v['amount'])
    resource_capacity[res] = resource_capacity.get(res, 0) + amt
for record in CSVQA_DATA['logical_records'].get('usage', []):
    v = record['values']
    ref = v['item_ref']
    res = v['resource']
    amt = int(v['amount'])
    usage.setdefault(ref, {})[res] = amt
for record in CSVQA_DATA['logical_records'].get('bundle', []):
    v = record['values']
    a = v['item_a']
    b = v['item_b']
    bonus = int(v['bonus_cents'])
    bundle_params[a, b] = bonus
for record in CSVQA_DATA['logical_records'].get('requires', []):
    v = record['values']
    i = v['item_ref']
    j = v['prerequisite_ref']
    requires.append((i, j))
for record in CSVQA_DATA['logical_records'].get('incompatible', []):
    v = record['values']
    a = v['item_a']
    b = v['item_b']
    incompatible.append((a, b))
quantity = {i: m.addVar(vtype=GRB.INTEGER, name=f'q_{i}') for i in item_params}
selected = {i: m.addVar(vtype=GRB.BINARY, name=f'z_{i}') for i in item_params}
category_active = {c: m.addVar(vtype=GRB.BINARY, name=f'y_{c}') for c in category_params}
bundle_active = {k: m.addVar(vtype=GRB.BINARY, name=f'b_{k[0]}_{k[1]}') for k in bundle_params}
for i, p in item_params.items():
    m.addConstr(p['min_lot'] * selected[i] <= quantity[i])
    m.addConstr(quantity[i] <= p['max_order'] * selected[i])
for c, p in category_params.items():
    cat_items = [i for i, ip in item_params.items() if ip['category'] == c]
    sum_q = gurobipy.quicksum((quantity[i] for i in cat_items))
    m.addConstr(sum_q >= p['min_q'])
    m.addConstr(sum_q <= p['max_q'])
for c, p in category_params.items():
    cat_items = [i for i, ip in item_params.items() if ip['category'] == c]
    sum_q = gurobipy.quicksum((quantity[i] for i in cat_items))
    M_c = p['max_q']
    m.addConstr(sum_q <= M_c * category_active[c])
    m.addConstr(sum_q >= category_active[c])
for (a, b), bonus in bundle_params.items():
    var = bundle_active[a, b]
    m.addConstr(var <= selected[a])
    m.addConstr(var <= selected[b])
    m.addConstr(var >= selected[a] + selected[b] - 1)
for i, j in requires:
    m.addConstr(selected[i] <= selected[j])
for a, b in incompatible:
    m.addConstr(selected[a] + selected[b] <= 1)
for r, cap in resource_capacity.items():
    sum_res = gurobipy.quicksum((usage.get(i, {}).get(r, 0) * quantity[i] for i in item_params))
    m.addConstr(sum_res <= cap)
obj = gurobipy.quicksum((item_params[i]['unit_benefit'] * quantity[i] for i in item_params)) - gurobipy.quicksum((item_params[i]['item_fee'] * selected[i] for i in item_params)) - gurobipy.quicksum((category_params[c]['activation_fee'] * category_active[c] for c in category_params)) + gurobipy.quicksum((bundle_params[a, b] * bundle_active[a, b] for a, b in bundle_params))
m.setObjective(obj, GRB.MAXIMIZE)
m.optimize()
